SELECT pancreactomy2_1.nppes_provider_last_org_name AS nppes_provider_last_org_name,   pancreactomy2_1.nppes_provider_state AS nppes_provider_state,   CAST(pancreactomy2_1.nppes_provider_zip AS BIGINT) AS nppes_provider_zip,   pancreactomy2_1.provider_type AS provider_type,   SUM(pancreactomy2_1.line_srvc_cnt) AS sum_line_srvc_cnt_ok FROM pancreactomy2_1 WHERE (pancreactomy2_1.hcpcs_description = 'Imaging of pancreatic duct for placement of catheter using an endoscope') GROUP BY pancreactomy2_1.nppes_provider_last_org_name,   pancreactomy2_1.nppes_provider_state,   pancreactomy2_1.nppes_provider_zip,   pancreactomy2_1.provider_type,   pancreactomy2_1.nppes_provider_zip;
